    if[(v<1000000000)&(v>=-1000000000);1b];
    0b};
  tryf:{[s]
    s:norm s;
    if[not count s;0b];
    if[not all s in "0123456789.";0b];
    if[(count s)>(1+count where "."=s);0b];
    if["."~(first s)&"."~last s;0b];
    if[not (count where "."=s);1b];
    if[not (count where "."=s);1b];
    if[not (count where s in "0123456789");0b];
    if[(1000000f>abs "F"$s);1b];
    0b};
  tryb:{[s]
    s:lower s;
    s in ("0";"1";"t";"f";"true";"false")};
  tryc:{[s]
