  syms:();syminx:();effective:();longs:();floats:();bools:();chars:();recast:0;total:0f;i:0;
  while[i<count tokens;tok:tokens i;code:codes i;ok:0;effcode:code;
    case[code~"j";ok:tryj tok];
    code~"f";ok:tryf tok];
    code~"b";ok:tryb tok];
    code~"c";ok:tryc tok];
    code~"s";ok:1b];
    if[not ok;j:0;while[(j<count `j`f`b`c`s)&not ok;alt:(`j`f`b`c`s)j;
      if[not alt~`$code;
